INSERT INTO `<table_name>` (`VIEW_DEFINITION`) VALUES ('select `b`.`book_id` AS `book_id`,`b`.`title` AS `title`,`b`.`subtitle` AS `subtitle`,`b`.`original_title` AS `original_title`,coalesce((select group_concat(`p`.`name` order by `bp`.`role_order` ASC separator \'、\') from (`books`.`book_persons` `bp` join `books`.`persons` `p` on(`p`.`person_id` = `bp`.`person_id`)) where `bp`.`book_id` = `b`.`book_id` and `bp`.`role` = \'author\'),`b`.`author`) AS `author`,coalesce((select group_concat(`p`.`name` order by `bp`.`role_order` ASC separator \'、\') from (`books`.`book_persons` `bp` join `books`.`persons` `p` on(`p`.`person_id` = `bp`.`person_id`)) where `bp`.`book_id` = `b`.`book_id` and `bp`.`role` = \'translator\'),`b`.`translator`) AS `translator`,coalesce((select `cano`.`name_zh` from ((`books`.`editions` `e` join `books`.`publishers` `pub` on(`pub`.`publisher_id` = `e`.`publisher_id`)) join `books`.`publishers` `cano` on(`cano`.`publisher_id` = coalesce(`pub`.`canonical_id`,`pub`.`publisher_id`))) where `e`.`book_id` = `b`.`book_id` order by `e`.`edition_id` limit 1),`b`.`publisher`) AS `publisher`,coalesce((select `e`.`publish_date` from `books`.`editions` `e` where `e`.`book_id` = `b`.`book_id` and `e`.`publish_date` is not null order by `e`.`publish_date` desc limit 1),`b`.`publish_date`) AS `publish_date`,coalesce((select `i`.`id_value` from (`books`.`identifiers` `i` join `books`.`editions` `e` on(`e`.`edition_id` = `i`.`edition_id`)) where `e`.`book_id` = `b`.`book_id` and `i`.`id_type` = \'ISBN13\' order by `i`.`identifier_id` limit 1),`b`.`isbn13`) AS `isbn13`,coalesce((select `m`.`url_or_path` from (`books`.`media` `m` join `books`.`editions` `e2` on(`e2`.`edition_id` = `m`.`edition_id`)) where `e2`.`book_id` = `b`.`book_id` and `m`.`media_type` = \'cover\' order by `m`.`is_primary` desc,`m`.`media_id` limit 1),`b`.`cover_url`) AS `cover_url`,`b`.`summary_short` AS `summary_short`,`b`.`summary` AS `summary`,`b`.`category_id` AS `category_id`,`b`.`source` AS `source`,`b`.`is_published` AS `is_published`,`b`.`created_at` AS `created_at` from `books`.`books` `b`');
